// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 value) public {
        // admissible domain: value should fit in balance and sender must be non-zero
        vm.assume(sender != address(0));
        // bound value to a reasonable range but allow very large values to trigger overflow wrapping
        value = bound(value, 0, type(uint256).max);

        // ensure sender has funds to send
        vm.deal(sender, value);

        // record before
        uint256 before = c.depositsCount();

        // perform the external payable call as sender to trigger receive()
        vm.prank(sender);
        // call the bare receive by sending value with empty data
        (bool ok,) = address(c).call{value: value}("\x00");
        // the contract's receive does not revert in either version, so ok should be true
        // but we don't assert on ok specifically; we only observe depositsCount through the getter

        uint256 after = c.depositsCount();

        // General rule: depositsCount must never decrease after a deposit (non-decreasing)
        assertTrue(after >= before);
    }
}

