// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the initial depositsCount (by making that many prior 0-value calls to receive)
    // and the number of further deposits to perform; both are uint256 so fuzzer can find overflow-triggering sizes
    function testFuzz_property(uint256 initialCalls, uint256 extraCalls) public {
        // keep domains wide but avoid extremely expensive runs by bounding to a reasonable upper limit
        // still allow very large values to detect wrapping behavior
        initialCalls = bound(initialCalls, 0, 2**16); // up to 65536 prior calls
        extraCalls = bound(extraCalls, 0, 2**16);     // up to 65536 further calls

        // make initialCalls many zero-ether receive() invocations to set depositsCount to a chosen start
        for (uint256 i = 0; i < initialCalls; ++i) {
            // call receive() by sending a 0-value transaction from an EOA
            vm.prank(address(uint160(uint256(keccak256(abi.encodePacked(i, initialCalls))))));
            (bool ok,) = address(c).call{value: 0}("");
            require(ok); // these should not revert
        }

        uint256 before = c.depositsCount();

        // perform extraCalls further zero-ether receive() invocations
        for (uint256 j = 0; j < extraCalls; ++j) {
            vm.prank(address(uint160(uint256(keccak256(abi.encodePacked(j, extraCalls))))));
            (bool ok,) = address(c).call{value: 0}("");
            require(ok);
        }

        uint256 after = c.depositsCount();

        // General rule: after == before + extraCalls for the correct contract (no wrapping)
        assertTrue(after == before + extraCalls);
    }
}

