pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: starting depositsCount to set up the contract state by performing many dummy receives
    function testFuzz_property(uint256 nCalls) public {
        // keep nCalls in a wide but reasonable bound to avoid extremely long loops in the fuzzer
        // We allow up to 1000 calls in the fuzzer run; this still lets fuzzer find wrap by setting nCalls near 2**256-1
        uint256 boundCalls = bound(nCalls, 0, 1000);

        // make boundCalls calls to receive to advance depositsCount to a variety of values
        // Use an actor who sends 1 wei each time
        address actor = address(0xBEEF);
        vm.deal(actor, 1 ether);
        for (uint256 i = 0; i < boundCalls; i++) {
            vm.prank(actor);
            // send 1 wei to trigger receive()
            (bool ok, ) = address(c).call{value: 1}('');
            require(ok);
        }

        // record before
        uint256 before = c.depositsCount();

        // perform a single receive call from a fuzzed actor and amount: we fuzz amount by deriving from nCalls
        // Use the fuzzer-provided nCalls again to produce a varied sender amount and actor
        uint256 amount = uint256(keccak256(abi.encodePacked(nCalls))) & ((1 << 64) - 1);
        address sender = address(uint160(uint256(keccak256(abi.encodePacked(nCalls, before)))>>96));
        vm.deal(sender, amount + 1);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: amount}('');
        require(ok2);

        uint256 after = c.depositsCount();

        // General property: a single successful receive call increases depositsCount by exactly 1
        assertTrue(after == before + 1);
    }
}

