pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: starting depositsCount (we cannot write directly to c.depositsCount, but we can perform many receives)
    // and an actor who sends value; we will drive c through one final receive and assert non-decreasing behavior
    function testFuzz_property(uint256 preCalls, address actor, uint256 value) public {
        // Keep domains wide but sensible
        // cap preCalls to a reasonably large number to avoid running out of gas in tests
        preCalls = bound(preCalls, 0, 300);
        // actor must be non-zero
        vm.assume(actor != address(0));
        // give the actor some ETH to send
        vm.deal(actor, value);

        // First, drive c through `preCalls` receive calls to set an arbitrary starting depositsCount
        for (uint256 i = 0; i < preCalls; ++i) {
            vm.prank(actor);
            // send 1 wei for the preparatory calls (value can be zero or more; we only need to trigger receive)
            (bool ok, ) = address(c).call{value: 1}("");
            // ensure the preparatory calls succeed (they should on the reference contract)
            require(ok);
        }

        // read depositsCount before the decisive single receive
        uint256 before = c.depositsCount();

        // make the decisive receive call with fuzzed value (may be zero)
        vm.prank(actor);
        (bool okDecisive, ) = address(c).call{value: value}("");
        require(okDecisive);

        uint256 after = c.depositsCount();

        // General rule: a single receive call never decreases depositsCount (non-decreasing)
        assertTrue(after >= before);
    }
}

