pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz param: amount of wei sent by an adversarial sender
    function testFuzz_property(uint256 amount) public {
        // keep amount within a reasonable range but wide enough
        amount = bound(amount, 0, 1 ether);

        // deploy an adversarial helper that will revert on receiving Ether
        Reverter r = new Reverter();

        // fund the reverter so that sending to it could be attempted by the contract
        vm.deal(address(this), 1 ether);

        // We will make the test contract be the msg.sender of the payable call into C.
        // The reference C's receive() has a require that would prevent depositsCount++ if the call context would revert.
        // To simulate a scenario where the external context would revert, we will have the contract C attempt to send or otherwise interact
        // with the Reverter in a way that causes a revert only if the mutant removed the guard. However, the concrete difference described
        // is that the require prevented state change on revert — we can force a revert by making C's receive() run in the same transaction
        // but cause a lower-level revert during the payable call: do a direct call to C.receive by sending Ether while making the caller
        // be a contract whose fallback reverts. Since the fuzzer cannot supply a contract, we deploy Reverter and then have it call C.

        // Have Reverter attempt to send Ether to C via a payable call. The Reverter will forward the provided amount to C in a call
        // and then revert after (its fallback will revert when receiving Ether if desired). We want the transfer into C to fail inside C
        // only for the mutant; but since the mutant difference is removal of a require that guarded against a revert, the simplest distinguishing
        // behavior is to have the caller (ReverterCaller) call C with value but then revert after the call — ensuring that in reference C, depositsCount
        // does not increase because the overall call reverted, whereas the mutant increments unconditionally during execution before revert.

        // Deploy a caller that sends value to C and then forces a revert after the call returns to simulate a failing caller transaction
        RevertingCaller caller = new RevertingCaller(address(c));

        // fund caller so it can send value
        vm.deal(address(caller), amount);

        // Record depositsCount before
        uint before = c.depositsCount();

        // Make the caller perform the external call into C with value; the caller will revert at the end of its operation.
        bool ok;
        try caller.invokeReceive{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C guarantees: if the overall caller transaction reverted (ok == false), depositsCount must NOT have increased.
        // The mutant increments unconditionally, so there exist amounts where ok == false but depositsCount > before.
        // We assert the general invariant: if the outer call reverted, depositsCount is unchanged.
        if (!ok) {
            assertTrue(c.depositsCount() == before);
        } else {
            // If the call did not revert, depositsCount may increase; still assert non-decrease (guarding against underflow etc.)
            assertTrue(c.depositsCount() >= before);
        }
    }
}

// Caller contract that sends value to C and then reverts to simulate a failing caller (adversarial environment)
contract RevertingCaller {
    address payable public target;
    constructor(address _target) payable {
        target = payable(_target);
    }

    // invokeReceive will forward all gas and value to target (triggering its receive) and then revert
    function invokeReceive() external payable {
        // Call the target's receive by sending value with an empty calldata
        (bool sent, ) = target.call{value: msg.value}("");
        // ignore sent result; then revert to simulate a failing caller
        revert("forced revert after call");
    }
}

// Minimal helper that would revert on receive if used directly (not used here but provided per problem guidance)
contract Reverter {
    fallback() external payable {
        revert("revert in fallback");
    }
    receive() external payable {
        revert("revert in receive");
    }
}

