pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: sender address and amount of ETH to send
    function testFuzz_property(address sender, uint256 amount) public {
        // admissible domain: sender must be non-zero and not the contract itself
        vm.assume(sender != address(0));
        vm.assume(sender != address(this));
        // bound the amount to a reasonable max so vm.deal works in tests
        amount = bound(amount, 0, 1 ether);

        // Deploy adversarial helper that always reverts on receive to simulate a failing external condition
        Reverter rev = new Reverter();

        // fund the sender so it can send ETH
        vm.deal(sender, amount + 1 wei);

        // make sender attempt to send ETH to c; the difference hinges on whether the call reverts
        // we route the sender's behavior through a small proxy that forwards to c but reverts (adversary)
        // Here we make sender call a forwarder which in its fallback will attempt to call c with value

        // Deploy a Forwarder under sender's control to perform the call to c and then trigger the reverter as beneficiary
        vm.startPrank(sender);
        Forwarder f = new Forwarder();
        vm.stopPrank();

        // Fund the forwarder if necessary
        vm.deal(address(f), amount);

        // Now have the forwarder attempt to send ETH to c, but before that we set the forwarder's target beneficiary
        // to be the Reverter so that when c does any external interaction (none in receive), we still simulate
        // a realistic external failing callee by making the forwarder itself call c with value and then call the reverter.

        // Execute: the forwarder will attempt a low-level call to c (triggering receive) with the given amount.
        // Wrap to capture whether the call to c succeeded from the caller's perspective.
        bool ok;
        try f.callReceive{value: amount}(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property we assert: when the receive call completes without revert (ok == true), depositsCount increased by 1;
        // when it reverts (ok == false), the reference C ensures depositsCount did NOT increase. Since we must write a single assertion
        // that holds for the reference for all inputs, and fails for the mutant for some input, we assert that if the external call reverted
        // then depositsCount == 0 (since setUp made fresh contract with 0). The reference preserves that; the mutant increments regardless and
        // will make this assertion fail for the adversarial reverter scenario.
        if (!ok) {
            // single assertion reading c's public getter
            assertTrue(c.depositsCount() == 0);
        } else {
            // if the call succeeded, depositsCount should be 1
            assertTrue(c.depositsCount() == 1);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}

// Minimal forwarder contract used by the fuzzed sender to call c's receive
contract Forwarder {
    // Allow receiving funds
    receive() external payable {}

    // Call the target (C) with provided ETH value; will bubble up revert to caller
    function callReceive(address target) external payable {
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok, "call failed");
    }
}

