pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address sender) public {
        // Keep amount reasonable but allow zero too; wide domain
        amount = bound(amount, 0, 1 ether);
        // Deploy an adversarial callee that will revert when receiving funds
        Reverter rev = new Reverter();

        // Fund the sender so it can send ETH
        vm.deal(sender, amount);
        // Prank as the adversarial reverter by making it the recipient of a low-level call
        // We simulate an external party that would cause a failure in some external interactions by having sender perform a call to c while the sender's code is the reverter.
        // To make msg.sender be the reverter contract, we have the reverter contract perform the low-level call to c. But fuzzer provides `sender`; ensure we can fund the reverter from sender by having sender send ETH to rev, then rev forwards to c and reverts inside.

        // Fund the reverter from the fuzzed sender (if sender has no funds this will be a no-op but still admissible)
        if (amount > 0) {
            vm.prank(sender);
            // send ETH to reverter so it has balance to attempt the call
            (bool s,) = address(rev).call{value: amount}("");
            // ignore success of this funding step
        }

        // Now have the reverter attempt to call c's receive by forwarding value and then reverting in its own fallback
        // The reverter's attack function will try to forward the funds to c which will trigger c.receive
        bool ok;
        try rev.attack{value: amount}(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: on the correct contract, if the call reverted then depositsCount did not increase; equivalently, depositsCount equals 1 iff the call succeeded (starting from 0).
        // We assert the correct contract's behavior: if ok is true then depositsCount == 1, otherwise depositsCount == 0.
        // This single assertTrue reads c's public getter.
        if (ok) {
            assertTrue(c.depositsCount() == 1);
        } else {
            assertTrue(c.depositsCount() == 0);
        }
    }
}

// Helper that reverts during its fallback, and provides an attack method that forwards funds to target (which triggers target.receive)
contract Reverter {
    // Attack: attempt to send value to target, then revert to simulate failing external party
    function attack(address target) external payable {
        // forward the funds to target via call which triggers target.receive
        (bool sent, ) = target.call{value: msg.value}("");
        // ignore the result; after attempting, revert to simulate failing party
        revert("revert after call");
    }

    // Accept ETH so we can fund this contract
    receive() external payable {}
}

